#!/usr/bin/env python3
import json
import os

exercises = []
used_names = set()

def add_ex(name, difficulty, score, equipment, environment, instructions):
    clean_name = name.strip()
    norm = clean_name.lower()
    if norm in used_names:
        raise ValueError(f"Duplicate exercise detected: {clean_name}")
    used_names.add(norm)
    exercises.append({
        "id": f"back_{len(exercises) + 1}",
        "name": clean_name,
        "muscleGroup": "Back",
        "difficulty": difficulty,
        "scientificEffectivenessScore": round(float(score), 1),
        "equipmentNeeded": equipment,
        "environment": environment,
        "instructions": instructions.strip()
    })

